-- M1-02: core identity tables and the subject catalogue (PRODUCT-SPEC 8.2).
-- Conventions: UUID v7 ids generated by the application; timestamptz in UTC;
-- no physical deletes (statuses, *_at columns); statuses as text + CHECK so they evolve without enum DDL.

CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- account = person, identified by Telegram user ID (spec 3.1)
CREATE TABLE account (
  id                uuid PRIMARY KEY,
  telegram_user_id  bigint NOT NULL UNIQUE,
  first_name        text NOT NULL DEFAULT '',
  last_name         text NOT NULL DEFAULT '',
  username          text,
  timezone          text NOT NULL DEFAULT 'Europe/Minsk',
  locale            text NOT NULL DEFAULT 'ru',
  status            text NOT NULL DEFAULT 'onboarding'
                    CHECK (status IN ('invited', 'onboarding', 'active', 'blocked')),
  blocked_at        timestamptz,
  blocked_by        uuid REFERENCES account(id),
  block_reason      text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX account_username_idx ON account (lower(username)) WHERE username IS NOT NULL;
CREATE INDEX account_status_idx ON account (status);
CREATE TRIGGER account_set_updated_at BEFORE UPDATE ON account
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- roles; revoked_at keeps history instead of deleting (spec 1.4.6)
CREATE TABLE account_role (
  id          uuid PRIMARY KEY,
  account_id  uuid NOT NULL REFERENCES account(id),
  role        text NOT NULL CHECK (role IN ('SUPER_ADMIN', 'ADMIN', 'TEACHER', 'STUDENT', 'PARENT')),
  granted_by  uuid REFERENCES account(id),
  granted_at  timestamptz NOT NULL DEFAULT now(),
  revoked_at  timestamptz,
  revoked_by  uuid REFERENCES account(id)
);
CREATE UNIQUE INDEX account_role_active_uniq ON account_role (account_id, role) WHERE revoked_at IS NULL;
-- exactly one active super admin on the platform (spec 3.2)
CREATE UNIQUE INDEX account_role_single_super_admin ON account_role (role)
  WHERE role = 'SUPER_ADMIN' AND revoked_at IS NULL;
CREATE INDEX account_role_account_idx ON account_role (account_id);

-- per-bot chat channel of an account (spec 8.2, NTF-09)
CREATE TABLE bot_chat (
  id            uuid PRIMARY KEY,
  account_id    uuid NOT NULL REFERENCES account(id),
  bot           text NOT NULL CHECK (bot IN ('auth', 'staff', 'student', 'parent')),
  chat_id       bigint NOT NULL,
  is_reachable  boolean NOT NULL DEFAULT true,
  last_error    text,
  last_seen_at  timestamptz NOT NULL DEFAULT now(),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (account_id, bot)
);
CREATE TRIGGER bot_chat_set_updated_at BEFORE UPDATE ON bot_chat
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- versioned consent; on_behalf_of = child account for parents (spec 10.2)
CREATE TABLE consent (
  id            uuid PRIMARY KEY,
  account_id    uuid NOT NULL REFERENCES account(id),
  document      text NOT NULL,
  version       text NOT NULL,
  accepted_at   timestamptz NOT NULL DEFAULT now(),
  on_behalf_of  uuid REFERENCES account(id),
  source        text NOT NULL DEFAULT 'bot' CHECK (source IN ('bot', 'web', 'api', 'system')),
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX consent_account_idx ON consent (account_id, document);

-- platform subject catalogue maintained by admins (Р-31)
CREATE TABLE subject (
  id          uuid PRIMARY KEY,
  name        text NOT NULL,
  is_active   boolean NOT NULL DEFAULT true,
  position    integer NOT NULL DEFAULT 0,
  created_by  uuid REFERENCES account(id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX subject_name_uniq ON subject (lower(name));
CREATE TRIGGER subject_set_updated_at BEFORE UPDATE ON subject
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

